class Base {
public:
    // Virtual function requires VTable setup
    virtual void print() const { /* Base implementation */ }
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    // Overrides Base VTable entry
    void print() const override { /* Derived implementation */ }
};

// Vptr lookup and runtime dispatch
void execute(Base* ptr) {
    // Looks up function pointer via ptr->vptr
    ptr->print();
}

// Usage Example
Derived d;
execute(&d);
// If 'ptr' is Base*, calls Base::print() (if not overridden)
// If 'ptr' is Derived*, calls Derived::print() (if overridden)
